{
  "findings": [
    {
      "ref": "[D542]",
      "area": "contact",
      "claim": "A parent can link to their child's Roblox account and use parental controls.",
      "stance": "neutral",
      "quote": "In this tutorial, I show you how to add a parent on Roblox and then enable parental controls. This means a parent can link to their child's Roblox account and use parental controls."
    },
    {
      "ref": "[D542]",
      "area": "money",
      "claim": "Spending restrictions let parents set monthly spending limits and receive notifications of transactions.",
      "stance": "mitigation",
      "quote": "we can see spending restrictions we'll select that and here you can set monthly spending limits for your child by selecting that and then you can put a dollar amount and then that's the most they'll be able to spend that month Additionally you can get notifications if they spend money so we'll select spending notifications and you can have it send you a notification for all transactions High spend alerts or turn off the notifications"
    },
    {
      "ref": "[D542]",
      "area": "data",
      "claim": "The app collects a child's user ID and possibly other account data when linking a parent account.",
      "stance": "risk",
      "quote": "first enter your date of birth and then select create account now that we've created our parent account we need to verify that we're a parent we have two different ways to do that first we can verify with a credit card or just our ID if you're using your ID all you need to do is take a picture of the front and back of your ID they'll verify that that's a real ID and then you'll be in"
    },
    {
      "ref": "[D542]",
      "area": "age_gating",
      "claim": "Direct chat is only allowed if the child is over 13 years old.",
      "stance": "risk",
      "quote": "if they're in an experience they can chat in a private chat with anyone else in that game with them and you can turn this on but only if your child is over the age of 13"
    },
    {
      "ref": "[D542]",
      "area": "content",
      "claim": "Content maturity settings range from minimal (mild violence) to moderate (more violence, blood, gambling).",
      "stance": "neutral",
      "quote": "first content maturity select that and then here we can determine the content maturity of any games or experiences on Roblox that we want to allow them to play so the further left this is the lower that rating is so minimal this will be minimal mature content as you can see may contain occasional mild violence or light unrealistic blood things like like that now if you bring this closer to the right you're going to get into moderate mature content so this will have more violence more blood maybe gambling things like that"
    },
    {
      "ref": "[D542]",
      "area": "developer_record",
      "claim": "The developer has no reported fines, breaches, lawsuits or regulatory actions mentioned in the segment.",
      "stance": "neutral",
      "quote": "The segment contains no mention of fines, breaches, lawsuits or regulatory actions against the developer."
    }
  ]
}
